from lib import *
S = SS('s11')
steps = [
    step("五个自定义中间件 A=100、B=300、C=550、D=750、E=900 各自记录钩子:process_request 按数字从小到大 A B C D E,下载之后 process_response 反过来 E D C B A,最后才是 spider 回调。日志里 “Enabled downloader middlewares” 的顺序也是同一个顺序(从靠近引擎到靠近下载器):offsite 50 → 自定义 A → httpauth 300 → 自定义 B → downloadtimeout → defaultheaders → useragent 500 → retry 550 → 自定义 C → metarefresh 580 → httpcompression 590 → redirect 600 → cookies 700 → httpproxy 750 → 自定义 D → stats 850 → 自定义 E。数字小 = 离引擎近。", t=tl(S(1)), mark=lidx(S(1), 'E       process_response', 'A       process_response'), done=lidx(S(1), 'A       process_request', 'E       process_request', 'spider  callback'), kv=KV([['process_request', '数字从小到大:A B C D E'], ['process_response', '数字从大到小:E D C B A'], ['数字小', '离引擎近、先看到请求'], ['数字大', '离下载器近、先看到响应']], ['process_response'])),
    step("放在 HttpCompressionMiddleware(590)两侧的中间件,看到的是同一个响应的不同状态。服务器发 gzip:595 的中间件先处理响应,body 是 64 字节(压缩后的原样);590 解压之后,585 的中间件看到的是 2613 字节,spider 回调拿到的也是 2613。所以想看原始字节就放在数字比 590 大的位置,想处理解压后的内容放在比 590 小的位置。", t=tl(S(2)), mark=lidx(S(2), 'H595', 'L585'), done=lidx(S(2), 'spider  callback'), b=bars([['595 看到(压缩)', 64, '64 字节'], ['585 看到(解压)', 2613, '2613 字节']], 2613, mark=[0, 1]), kv=KV([['595(离下载器近)', 'gzip 字节,64'], ['590 HttpCompression', '解压'], ['585(离引擎近)', '解压后,2613']], ['595(离下载器近)'])),
    step("process_request 里直接返回 Response(C=550):D、E 的 process_request 和真正的下载都跳过——服务器收到 0 个请求;但所有中间件的 process_response 仍然都被调用,而且从 E 开始(E、D、C、B、A),包括没有机会处理请求的 D 和 E。spider 回调拿到的就是 C 造出来的 Response。", t=tl(S(3)), mark=lidx(S(3), 'E       process_response', 'D       process_response', 'spider  callback'), done=lidx(S(3), 'C       process_request'), kv=KV([['C 返回 Response', '跳过 D、E 的 process_request 和下载'], ['服务器', '0 个请求'], ['process_response', '仍然 E D C B A 全部调用']], ['process_response'])),
    step("process_request 里返回 Request(C=550,只对 /page 这么做):原来的 /page 请求作废,不下载;新请求 /other 回到调度器(scheduler/enqueued = 2),重新从 A 开始走一遍中间件链(A、C、E),下载后 E C A 依次 process_response,最后回调的 url 是 other。服务器只收到 /other。", t=tl(S(4)), mark=lidx(S(4), 'A       process_request     url=other'), done=lidx(S(4), 'url=page'), kv=KV([['返回 Request', '原请求作废,新请求重新入调度器'], ['新请求', '重新走完整的中间件链'], ['服务器', '只收到 /other']], ['返回 Request'])),
    step("process_response 里返回 Request(D=750,只对第一次):D 之后,更靠近引擎的 C、B、A 的 process_response 对 /page 都不再被调用(事件里只有 E、D);新请求 /replaced 回到调度器,从 A 开始重新走,这一次 D 不再替换,E D C B A 全部 process_response,回调拿到 /replaced 的响应。服务器共收到 /page、/replaced 两个请求。", t=tl(S(5)), mark=lidx(S(5), 'D       process_response    url=page', 'A       process_request     url=replaced'), done=lidx(S(5), 'E       process_response    url=page'), kv=KV([['D 返回 Request', 'C、B、A 看不到 /page 的响应'], ['新请求', '重新走中间件链'], ['服务器', '/page、/replaced']], ['D 返回 Request'])),
    step("下载失败(连接被拒,异常是 DownloadConnectionRefusedError)时 process_exception 按响应方向调用:E、C、A,没有谁处理,最后交给请求的 errback;让 D 在 process_exception 里返回一个 Response(body 是 rescued)则只调用 E、D 两个 process_exception,然后这个 Response 走正常的 process_response(E、D、C、A),回调拿到 rescued。", t=tl(S(6)), mark=lidx(S(6), 'D=750', 'rescued', 'errback'), done=lidx(S(6), '没有谁处理异常'), kv=KV([['没人处理', 'E C A 依次 process_exception → errback'], ['D 返回 Response', '在 D 处终止异常处理'], ['之后', '走正常的 process_response']], ['D 返回 Response'])),
]
A = mkarts('s11', 11, 'Scrapy,下载器中间件,process_request,process_response,中间件顺序,真实验证,动画演示',
    '实测下载器中间件的调用顺序:process_request 按数字从小到大、process_response 反过来;595 看到 gzip 的 64 字节、585 看到解压后的 2613 字节;process_request 返回 Response 时仍然调用全部 process_response;返回 Request 会重新走一遍中间件链;process_exception 按响应方向调用。',
    'DOWNLOADER_MIDDLEWARES 里的数字到底表示什么?请求和响应各按什么方向经过它们?中间件返回 Response 或 Request 会发生什么?这篇用五个自定义中间件加记录钩子,把每种情形的事件顺序一行行打出来。',
    [('小 → 大', 'process_request 的调用方向(process_response 反过来)'), ('64 vs 2613 字节', '595 与 585 的中间件看到的同一个 gzip 响应的 body 大小'), ('0 个', 'process_request 返回 Response 时服务器收到的请求数(process_response 仍全部调用)')],
    [('数字的含义', '<p>数字越小越靠近引擎:请求从小到大依次经过 <code>process_request</code>,下载完成后响应从大到小依次经过 <code>process_response</code>。</p>'),
     ('位置决定你看到什么', '<p>内置的 <code>HttpCompressionMiddleware</code> 在 590,放在它外侧(数字大)的中间件看到压缩的 body,放在内侧(数字小)的看到解压后的 body。</p>'),
     ('返回 Response', '<p><code>process_request</code> 返回 <code>Response</code> 会跳过后面的 <code>process_request</code> 和下载,但全部 <code>process_response</code> 仍然会按顺序调用。</p>'),
     ('返回 Request', '<p>无论从 <code>process_request</code> 还是 <code>process_response</code> 返回 <code>Request</code>,原流程中断,新请求回到调度器重新走。</p>'),
     ('process_response 返回 Request', '<p>返回 <code>Request</code> 的中间件之后(更靠近引擎)的 <code>process_response</code> 不再被调用。</p>'),
     ('异常', '<p>下载异常按响应方向依次调用 <code>process_exception</code>,谁返回 <code>Response</code> 谁就终止异常处理,并让这个 Response 走正常的 <code>process_response</code>。</p>')],
    steps,
    [ENV_Y + '。用工厂函数生成带记录钩子的中间件类,通过 spider 的 custom_settings 加入;内置中间件顺序取自 Scrapy 日志的 “Enabled downloader middlewares”',
     '没有验证:async def 版本的 process_request(2.19 支持);from_crawler 里抛 NotConfigured;中间件抛异常(不是下载异常)时的顺序;重试、重定向这类内置中间件返回 Request 与自定义的相互影响(只看了内置顺序);数字相同的两个中间件的先后(同一个数字只能出现一次,字典键不同的话顺序由实现决定)'],
    '中间件顺序')
